// JavaScript must be written in ECMAScript 5.1.

function main() {
    // 左cmd + a-z を「英数 → その文字」に変換する猶予（ミリ秒）。
    var threshold = 100;

    var letters = 'abdeghijklmnopqrtuwy1234567890'.split('');
    var manipulators = [];

    // 猶予内の左cmd→文字は、commandショートカットにせず「英数→文字」にする。
    letters.forEach(function (key) {
        manipulators.push({
            type: 'basic',
            parameters: {
                'basic.simultaneous_threshold_milliseconds': threshold,
            },
            from: {
                simultaneous: [
                    { key_code: 'left_command' },
                    { key_code: key },
                ],
                simultaneous_options: {
                    key_down_order: 'strict',
                },
                modifiers: {
                    optional: ['any'],
                },
            },
            to: [
                { key_code: 'japanese_eisuu' },
                { key_code: key },
            ],
        });
    });

    // 上の同時押しに該当しない場合も、左cmdを押したら必ず英数を送る。
    // 組み合わせの場合は通常のcommandキーとしても動作する。
    manipulators.push({
        type: 'basic',
        from: {
            key_code: 'left_command',
            modifiers: {
                optional: ['any'],
            },
        },
        parameters: {
            'basic.to_if_held_down_threshold_milliseconds': 300,
        },
        to: [
            {
                key_code: 'japanese_eisuu',
                repeat: false,
            },
            {
                key_code: 'left_command',
                lazy: true,
            },
        ],
        to_if_held_down: [
            {
                key_code: 'left_command',
            },
        ],
    });

    // 右cmdは従来どおり。
    manipulators.push({
        type: 'basic',
        from: {
            key_code: 'right_command',
            modifiers: {
                optional: ['any'],
            },
        },
        parameters: {
            'basic.to_if_held_down_threshold_milliseconds': 300,
        },
        to: [
            {
                key_code: 'right_command',
                lazy: true,
            },
        ],
        to_if_alone: [
            {
                key_code: 'japanese_kana',
            },
        ],
        to_if_held_down: [
            {
                key_code: 'right_command',
            },
        ],
    });

    // Jiffy 75（キーボード側で英数を割り当て済み）には適用しない。
    manipulators.forEach(function (m) {
        m.conditions = [
            {
                type: 'device_unless',
                identifiers: [{ vendor_id: 6421, product_id: 61167 }],
            },
        ];
    });

    return {
        description: '左cmdで常に英数（猶予内の左cmd+a-zは英数+文字）/ 右cmd単体でかな（rev 5）',
        manipulators: manipulators,
    };
}

main()
